class Solution {
public:
    long long maxPairStrength(vector<int>& nums) {
        auto gcd11 = [](int a, int b) {
            while (b) { int r = a % b; a = b; b = r; }
            return a;
        };
        long long best = 0;
        for (int i = 0; i < (int)nums.size(); ++i)
            for (int j = i + 1; j < (int)nums.size(); ++j) {
                long long g = gcd11(nums[i], nums[j]);
                best = max(best, (long long)(nums[i] / g) * (nums[j] / g));
            }
        return best;
    }
};
